initialProposal.cssAppend:
#main[data-route="reader"]{background:var(--canvas);}
.reader-toolbar{display:flex;flex-direction:column;flex-wrap:nowrap;align-items:stretch;gap:10px;margin-bottom:24px;padding-bottom:16px;border-bottom:1px solid var(--line);min-width:0;max-width:100%;}
.reader-toolbar .reader-location-row,.reader-toolbar .reader-action-row{display:flex;flex-wrap:wrap;align-items:flex-end;gap:8px;min-width:0;max-width:100%;}
.reader-toolbar .reader-location-row>.field{display:flex;flex-direction:column;align-items:stretch;gap:4px;min-width:0;margin:0;}
.reader-toolbar .reader-location-row>.field:first-child{flex:0 1 140px;width:140px;max-width:46%;}
.reader-toolbar .reader-location-row>.field:last-child{flex:1 1 0;width:auto;max-width:100%;}
.reader-toolbar .reader-location-row select{display:block;width:100%;max-width:100%;min-width:0;min-height:44px;box-sizing:border-box;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.reader-toolbar .reader-action-row>.btn,.reader-toolbar .reader-action-row>.more-menu>summary{flex:0 1 auto;width:auto;max-width:100%;min-height:44px;box-sizing:border-box;}
.reader-toolbar .reader-action-row>.more-menu{flex:0 1 auto;width:auto;max-width:100%;min-width:0;position:relative;}
.reader-toolbar .reader-action-row>.more-menu[open]{flex:1 1 100%;flex-basis:100%;width:100%;display:flex;flex-direction:column;align-items:flex-start;gap:8px;}
.reader-toolbar .reader-action-row>.more-menu>summary{display:inline-flex;align-items:center;list-style:none;cursor:pointer;padding:0 12px;border:1px solid var(--line);border-radius:8px;background:var(--canvas);color:var(--ink);}
.reader-toolbar .reader-action-row>.more-menu>summary::-webkit-details-marker{display:none;}
.reader-toolbar .reader-action-row>.more-menu[open]>summary{align-self:flex-start;}
.reader-toolbar .reader-action-row>.more-menu>.btn,.reader-toolbar .reader-action-row>.more-menu>[data-action="dialog:reference"]{flex:0 0 auto;width:auto;max-width:100%;min-height:44px;white-space:normal;}
@media (max-width:900px){
.reader-toolbar .reader-action-row>.btn-primary{flex:0 1 auto;width:auto;max-width:100%;}
}
#reviewState,#freshnessState{display:inline-flex;align-items:center;gap:6px;max-width:100%;min-height:28px;margin:0 8px 8px 0;padding:4px 8px;border:1px solid var(--line);border-radius:999px;background:var(--soft);color:var(--ink);font-size:13px;line-height:1.35;vertical-align:middle;}
#reviewState::before{content:"검토";flex:0 0 auto;padding:0 6px;border-radius:999px;background:var(--canvas);color:var(--muted);font-size:11px;}
#freshnessState::before{content:"원본";flex:0 0 auto;padding:0 6px;border-radius:999px;background:var(--canvas);color:var(--muted);font-size:11px;}
#freshnessState[data-state="source-changed"]{border-style:solid;border-color:var(--warn);color:var(--warn-ink);background:var(--soft);}
#freshnessState[data-state="unknown"]{border-style:dashed;border-color:var(--line);color:var(--ink);background:var(--canvas);}
#freshnessState[data-state="partial"]{border-style:dotted;border-color:var(--line);color:var(--ink);background:var(--canvas);}

