#freshnessState[data-state="current"]{border-style:solid;border-color:var(--line);background:var(--soft);color:var(--ink);}
/* Root integration: explicit small-screen groups and uncluttered metadata. */
.reader-view .page-meta{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:0}
.reader-view #reviewState,.reader-view #freshnessState{margin:0;padding:4px 8px}
.reader-view .page-meta time{font-size:12px;color:var(--muted);white-space:nowrap}
.reader-toolbar .reader-location-row>.field{font-size:12px}
.reader-view #simulationResult{padding:12px 14px;border-left:3px solid var(--line);background:var(--soft);font-size:14px;line-height:1.65}
@media(max-width:480px){
.reader-toolbar .reader-location-row>.field:first-child{flex:0 0 104px;width:104px;max-width:40%}
.reader-toolbar .reader-action-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}
.reader-toolbar .reader-action-row>.btn,.reader-toolbar .reader-action-row>.more-menu{width:100%;min-width:0;max-width:100%}
.reader-toolbar .reader-action-row>.more-menu>summary{display:flex;justify-content:center;width:100%;max-width:100%;min-height:44px}
.reader-toolbar .reader-action-row>.more-menu[open]{grid-column:1/-1;align-items:stretch}
.reader-toolbar .reader-action-row>.more-menu[open]>.btn,.reader-toolbar .reader-action-row>.more-menu[open]>[data-action="dialog:reference"]{width:100%;margin-right:0}
}
